def resolve_roots(frontend_arg: str | None, backend_arg: str | None):
    cwd = Path.cwd().resolve()

    fe_candidates = []
    be_candidates = []
    if frontend_arg:
        fe_candidates.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg:
        be_candidates.append(Path(backend_arg).expanduser().resolve())

    fe_candidates += [cwd, cwd / "LambdaVisionSuper", cwd.parent / "LambdaVisionSuper"]
    be_candidates += [cwd, cwd / "LambdaVisionSuperBackEnd", cwd.parent / "LambdaVisionSuperBackEnd"]

    frontend = next(
        (
            p for p in fe_candidates
            if (p / "src/App.tsx").exists()
            and (p / "src/Pages/SamplingGeometryLabPage.tsx").exists()
        ),
        None,
    )
    backend = next(
        (
            p for p in be_candidates
            if (p / "app/main.py").exists()
            and (p / "app/services/vision_labs/sampling_geometry").exists()
        ),
        None,
    )

    if frontend is None:
        raise RuntimeError("Cannot locate LambdaVisionSuper frontend. Use --frontend /path/to/LambdaVisionSuper")
    if backend is None:
        raise RuntimeError("Cannot locate LambdaVisionSuperBackEnd. Use --backend /path/to/LambdaVisionSuperBackEnd")
    return frontend, backend


def real_path(frontend: Path, backend: Path, virtual: str) -> Path:
    if virtual.startswith("frontend/"):
        return frontend / virtual[len("frontend/"):]
    if virtual.startswith("backend/"):
        return backend / virtual[len("backend/"):]
    raise ValueError(virtual)


def modified_state(path: Path, old: str, new: str) -> str:
    if not path.exists():
        return "MISSING"
    current = path.read_text(encoding="utf-8")
    if current == new:
        return "OK"
    if current == old:
        return "UPDATE"
    return "CONFLICT"


def created_state(path: Path, desired: str) -> str:
    if not path.exists():
        return "CREATE"
    if path.read_text(encoding="utf-8") == desired:
        return "OK"
    return "CONFLICT"


def route_state(frontend: Path, backend: Path):
    app_text = (frontend / "src/App.tsx").read_text(encoding="utf-8")
    api_text = (backend / "app/api/v1/api.py").read_text(encoding="utf-8")

    if SAMPLING_APP_MARKER not in app_text:
        app_state = "MISSING-BASE"
    elif CONTOUR_APP_IMPORT in app_text and "/labs/contour-extractor" in app_text:
        app_state = "OK"
    else:
        app_state = "PATCH"

    if SAMPLING_API_MARKER not in api_text or "sampling_geometry_api" not in api_text:
        api_state = "MISSING-BASE"
    elif CONTOUR_API_IMPORT in api_text and 'prefix="/contour-extractor"' in api_text:
        api_state = "OK"
    else:
        api_state = "PATCH"

    return app_state, api_state


def scan(frontend: Path, backend: Path):
    print("=" * 98)
    print("VISION LABS V0.3.0 — CONTOUR EXTRACTOR / SAMPLING ARCHITECTURAL SPLIT")
    print("=" * 98)
    print(f"Frontend : {frontend}")
    print(f"Backend  : {backend}")
    print()

    conflicts = 0
    for virtual, payload in MODIFIED.items():
        state = modified_state(real_path(frontend, backend, virtual), payload["old"], payload["new"])
        print(f"  [{state:12}] {virtual}")
        if state in {"CONFLICT", "MISSING"}:
            conflicts += 1

    for virtual, desired in CREATED.items():
        state = created_state(real_path(frontend, backend, virtual), desired)
        print(f"  [{state:12}] {virtual}")
        if state == "CONFLICT":
            conflicts += 1

    app_state, api_state = route_state(frontend, backend)
    print(f"  [{app_state:12}] frontend/src/App.tsx")
    print(f"  [{api_state:12}] backend/app/api/v1/api.py")
    if "MISSING" in app_state or "MISSING" in api_state:
        conflicts += 1

    print()
    print("Architecture:")
    print("  Contour Extractor LAB:")
    print("    candidate generation -> DEFAULT EARLY FILTER -> single-copy ContourStore")
    print("    -> ID-only filter funnel -> lazy geometry inspection -> ContourSet service")
    print("  Sampling LAB:")
    print("    Spatial Sampling Unit = Housing (WHERE) + Data Extractor (WHAT/HOW)")
